      "Faites fondre le beurre à feu vif dans la sauteuse et faites-y dorer le navet 2 à 3 minutes. Ajoutez ensuite un peu d'eau (environ 60 ml pour 2 personnes), couvrez et laissez mijoter à feu moyen pendant 5 à 8 minutes. Assaisonnez. Dans une casserole d'eau bouillante, cuisez le boulgour durant 10 minutes puis égouttez-le.",
