      "Assaisonnez le boulgour tiède avec le sachet d'Hello Umami, un filet d'huile d'olive, du sel et du poivre. Répartissez les épinards au fond des assiettes, ajoutez le boulgour, les cubes de navet, les tranches de pomme et le fromage de chèvre. Arrosez de vinaigrette balsamique puis décorez avec les graines de courge et les herbes fraîches."
