      "Faites grilloter à sec les graines de courge dans une seconde poêle chauffée à vif jusqu'à ce qu'elles sautent légèrement, puis réservez-les. Découpez la courgette en petits cubes. Dans la poêle ayant servi aux graines, faites rissoler la courgette avec une demi-cuillère à soupe d'huile de tournesol pendant 4 à 5 minutes à feu moyen-vif. Incorporez le miel, poursuivez 1 minute de plus, puis salez et poivrez.",
