      "Coupez les radis en rondelles fines après avoir retiré les fanes. Dans un petit bol, préparez une marinade en mélangeant la moitié du vinaigre de vin blanc et du miel avec un peu de sel, puis immergez-y les radis et remuez de temps en temps.",
      "Récupérez le jus de marinade de la poitrine de porc puis découpez la viande en tranches d'un demi-centimètre. Dans une poêle chaude avec un filet d'huile, faites revenir la viande environ 12 minutes. Versez ensuite le jus de marinade ainsi que la sauce hoisin et laissez frémir le tout pendant 2 minutes.",
      "Tranchez grossièrement la salade little gem. Dans un grand récipient, préparez l'assaisonnement en fouettant la purée de gingembre, l'huile de sésame, la sauce soja, le restant de vinaigre et le restant de miel. Incorporez la salade, le mélange de choux-carottes, les fèves de soja et la moitié des radis marinés, puis assaisonnez à votre convenance.",
