      "Dans chaque verre, versez 150 ml d'eau avec 2 cuillères à soupe de vinaigre de vin blanc, puis cassez-y un œuf de manière qu'il soit totalement immergé. Laissez reposer. Dans un bol séparé, râpez la carotte, assaisonnez-la avec le sucre, 1 cuillère à soupe de vinaigre, du sel et du poivre, puis mélangez et réservez.",
      "Faites bouillir l'eau dans une casserole pour y cuire le riz 12 à 15 minutes, puis égouttez-le et gardez-le au chaud. Préparez la garniture en éminçant l'oignon, en taillant les champignons en lamelles et en hachant l'ail. Préparez ensuite la sauce en mélangeant la mayonnaise avec la sauce kimchi selon votre tolérance au piquant, ainsi qu'un peu de sel et poivre. Faites revenir l'oignon dans une poêle avec 1 cuillère à soupe d'huile de tournesol durant 4 à 6 minutes.",
