      "Incorporez les linguine égouttées dans la sauteuse afin de bien les enrober de sauce. Ajoutez ensuite la moitié des courgettes rôties, la moitié des crevettes, une cuillère à café de jus de citron par personne et une pincée de zeste, puis mélangez délicatement.",
