      "Hachez l'ail, équeutez et coupez les haricots verts en deux, puis détaillez la carotte jaune en fines demi-rondelles. Dans une sauteuse à feu moyen-vif avec de l'huile d'olive, faites suer la moitié de l'ail pendant 1 minute. Ajoutez les carottes et les haricots, faites revenir 2 à 3 minutes, assaisonnez de sel et de poivre, puis versez 6 cuillères à soupe d'eau. Couvrez et laissez cuire 8 à 10 minutes. Ciselez l'aneth pendant ce temps.",
