      "Faite chauffer la moitié de l'huile d'olive dans une grande sauteuse réglée sur feu moyen-vif. Faites-y revenir l'oignon, le poivron pointu et les épices orientales pendant 3 minutes. Incorporez la viande hachée et poursuivez la cuisson 3 à 5 minutes. Rectifiez le salage et le poivrage, puis gardez au chaud sous un couvercle.",
      "Dans un petit récipient, mélangez l'eau et le reste d'huile d'olive. Badigeonnez un côté de chaque tortilla avec ce mélange, puis saupoudrez de zaatar. Disposez-les sur une plaque recouverte de papier cuisson et enfournez 3 minutes. Pendant ce temps, fouettez le fromage frais avec les deux tiers du sumac et le jus d'orange pressé.",
      "Tartinez la face nature des tortillas chaudes avec la préparation au fromage frais. Garnissez avec le mélange de légumes sautés, la viande hachée et la salsa tomate-orange. Saupoudrez avec les herbes ciselées et le restant de sumac, ajoutez un filet de miel selon votre goût, puis rabattez les côtés des tortillas."
