      "Tranchez la moitié de l'oignon rouge en dés et le reste en lanières à réserver. Hachez l'échalote en dés. Faites revenir les dés d'oignon et d'échalote dans une poêle avec un filet d'huile d'olive, puis mettez-les de côté.",
